use vstd::prelude::*;

verus! {
    fn f(n: i8) -> i8 {
        if n >= 4 {
            n % 2
        } else {
            4 - n
        }
    }

    fn solve(queries: Vec<i8>) -> (results: Vec<i8>)
        requires
            queries.len() <= 128, // Since i8 can hold values from -128 to 127
            forall(|i: usize| i < queries.len() ==> queries[i] >= 2),
        ensures
            results.len() == queries.len(),
            forall(|i: usize| i < queries.len() ==> results[i] == f(queries[i])),
    {
        let mut results: Vec<i8> = Vec::new();
        let mut idx: usize = 0;

        while idx < queries.len()
            invariant
                idx <= queries.len(),
                results.len() == idx,
                forall(|i: usize| i < idx ==> results[i] == f(queries[i])),
            decreases queries.len() - idx,
        {
            results.push(f(queries[idx]));
            idx = idx + 1;
        }

        results
    }
}

